package com.stylemind.commerce.entity;
import jakarta.persistence.Column; import jakarta.persistence.Entity; import jakarta.persistence.Id; import jakarta.persistence.Table; import java.time.OffsetDateTime; import java.util.UUID; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter;
@Entity @Table(name="order_status_history",schema="public") @Getter @Setter @NoArgsConstructor
public class OrderStatusHistory { @Id @Column(name="history_id") private UUID historyId; @Column(name="order_id",nullable=false) private UUID orderId; @Column(name="from_status") private String fromStatus; @Column(name="to_status",nullable=false) private String toStatus; @Column(name="actor_user_id") private UUID actorUserId; @Column(name="changed_at",nullable=false) private OffsetDateTime changedAt; @Column(name="reason") private String reason; }
